# Bảo máy làm đi làm lại một việc
for i in range(3):
    print("Bi vỗ tay")

# range(1, 5) cho 1, 2, 3, 4. Không lấy số 5.
for i in range(1, 5):
    print(i)

# end="" là in xong đứng yên, không xuống dòng
for i in range(5):
    print("*", end="")
print()

for i in range(2):
    print("Na nhảy dây")

for i in range(3, 6):
    print(i)

for i in range(1, 4):
    print(i, "ngôi sao")

for i in range(6):
    print("*", end="")
print()

